/* ============================================================
   12 - Round6 内联敦煌飞天壁画源图
   来源：用户随 Round6 包提供的 generated-mural-reference.png，经降饱和、缩放和 JPEG 压缩。
   只作为墙面矿物色层的纹理源，不作为整屏背景或佛像替代。
   ============================================================ */
const ROUND6_MURAL_SOURCE = 'data:image/jpeg;base64,';
let ROUND6_MURAL_IMAGE = null;
function loadRound6MuralSource() {
  if (ROUND6_MURAL_IMAGE) return Promise.resolve(ROUND6_MURAL_IMAGE);
  return new Promise((resolve,reject)=>{
    const img=new Image();
    img.onload=()=>{ROUND6_MURAL_IMAGE=img;resolve(img);};
    img.onerror=reject;
    img.src=ROUND6_MURAL_SOURCE;
  });
}
